def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    if not os.path.exists(session_file):
        print(f"Session file not found: {session_file}")
        return {}
    content = open(session_file).read()
    grids = {}
    in_grid = False
    current_key = None
    current_rows = []
    current_h, current_w = 0, 0

    for line in content.split('\n'):
        if 'Demo pair' in line or 'Test input' in line:
            # Save previous grid if any
            if current_key and current_rows:
                if all(len(r) == current_w and all(c.isdigit() for c in r) for r in current_rows):
                    grids[current_key] = [[int(c) for c in r] for r in current_rows]

            # Parse new label
            match = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', line)
            if match:
                current_key = match.group(1)
                current_h, current_w = int(match.group(2)), int(match.group(3))
                current_rows = []
                in_grid = True
        elif in_grid:
            if line.strip() and len(line) <= current_w * 2:  # likely a grid row
                current_rows.append(line.strip())
            else:
                in_grid = False

    # Save last grid
    if current_key and current_rows:
        if all(len(r) == current_w and all(c.isdigit() for c in r) for r in current_rows):
            grids[current_key] = [[int(c) for c in r] for r in current_rows]

    return grids

