    in_test_input = False
    in_test_output = False
    current_marker = None

    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \(\d+x\d+\):'

    for line in lines:
        match = re.search(pattern, line)
        if match:
            # Save previous grid if in progress
            if in_demo_input or in_demo_output or in_test_input or in_test_output:
                if current_marker in grids:
                    if isinstance(current_grids[current_marker], list):
                        g = current_grids[current_marker]
                        if len(g) > 0 and all(isinstance(r, list) for r in g):
                            grids[current_marker] = g

            current_marker = match.group(1)
