                    row = stripped.split()
                    if in_demo_input or in_test_input:
                        current_grids[current_marker] = row
                else:
                    # Not a grid line, current marker might be done
                    if in_demo_input:
                        if current_marker in grids:
                            if isinstance(current_grids[current_marker], list):
                                g = current_grids[current_marker]
